void Add(TableLayoutPanel p,string label,Control c,int index){var wrap=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2,Margin=new Padding(4)};wrap.RowStyles.Add(new RowStyle(SizeType.Absolute,24));wrap.RowStyles.Add(new RowStyle(SizeType.Percent,100));wrap.Controls.Add(new Label{Text=label,AutoSize=true});c.Dock=DockStyle.Top;wrap.Controls.Add(c);p.Controls.Add(wrap,index%4,index/4);}void Set(ComboBox c,string[] values,string value){c.DropDownStyle=ComboBoxStyle.DropDownList;foreach(string v in values)c.Items.Add(v);if(!c.Items.Contains(value))c.Items.Add(value);c.SelectedItem=value;}
D Current(){items.EndEdit();List<D> rows=new List<D>();foreach(DataGridViewRow row in items.Rows){decimal qty,cost,sale;string qtyText=Convert.ToString(row.Cells[2].Value),costText=Convert.ToString(row.Cells[4].Value),saleText=Convert.ToString(row.Cells[5].Value);if(!Decimal.TryParse(qtyText,out qty)||qty<0||!Decimal.TryParse(costText,out cost)||cost<0)throw new Exception("수량과 원가 단가를 확인하세요.");D i=J.Row("category",Convert.ToString(row.Cells[0].Value),"name",Convert.ToString(row.Cells[1].Value),"qty",qty,"unit",Convert.ToString(row.Cells[3].Value),"cost",cost);if(!String.IsNullOrWhiteSpace(saleText)){if(!Decimal.TryParse(saleText,out sale)||sale<0)throw new Exception("판매단가를 확인하세요.");i["sale"]=sale;}i["spec"]=Convert.ToString(row.Cells[6].Value);rows.Add(i);}D result=J.Clone(q);result["name"]=title.Text.Trim();result["customer"]=((Choice)customer.SelectedItem).Id;result["shape"]=Convert.ToString(shape.SelectedItem);result["wood"]=Convert.ToString(wood.SelectedItem);result["led"]=Convert.ToString(led.SelectedItem);result["margin"]=margin.Value;result["vat"]=vat.Checked;result["items"]=rows.ToArray();result["note"]=note.Text;D spec=result.ContainsKey("specification")?J.Obj(result["specification"]):new D();spec["railing"]=Convert.ToString(railing.SelectedItem);spec["finish"]=Convert.ToString(finish.SelectedItem);result["specification"]=spec;return result;}
void UpdateSum(){if(!ready)return;try{D t=b.Call("totals",Current());sum.Text="["+J.Text(t,"taxMode")+" / 할인 "+J.Money(J.Num(t,"discount"))+"] 총원가  "+J.Money(J.Num(t,"cost"))+"     공급가  "+J.Money(J.Num(t,"sale"))+"     예상 이익  "+J.Money(J.Num(t,"profit"))+"\r\nVAT 포함 합계  "+J.Money(J.Num(t,"total"))+"   · 고정 판매단가에는 마진을 중복 가산하지 않습니다.";}catch(Exception ex){sum.Text=ex.Message;}}
void Save(){try{D result=Current();if(J.Text(result,"name")=="")throw new Exception("견적명을 입력하세요.");if(J.Rows(result,"items").Count==0)throw new Exception("항목을 추가하세요.");if(commit(result)){DialogResult=DialogResult.OK;Close();}}catch(Exception ex){MessageBox.Show(ex.Message,"견적 확인");}}
void Measurements(){D v=J.Row("steps",15,"width",900,"depth",270,"thick",30,"waste",10,"watts",10);using(var f=new EditForm("실측 물량 · 예시 치수이므로 현장 실측값으로 바꾸세요.",v,new[]{new Field("steps","단수","number"),new Field("width","발판 폭 mm","number"),new Field("depth","발판 깊이 mm","number"),new Field("thick","두께 mm","number"),new Field("waste","여유율 %","number"),new Field("watts","LED W/m","number")},null,x=>{decimal steps=J.Num(x,"steps"),w=J.Num(x,"width"),depth=J.Num(x,"depth"),thick=J.Num(x,"thick"),waste=J.Num(x,"waste");if(steps<=0||steps!=Math.Floor(steps)||w<=0||depth<=0||thick<=0||waste>100){MessageBox.Show("단수·치수·여유율을 확인하세요.");return false;}decimal volume=steps*w*depth*thick/1000000000m*(1+waste/100),length=steps*w/1000m*(1+waste/100);foreach(DataGridViewRow r in items.Rows){string n=Convert.ToString(r.Cells[1].Value);if(n=="계단 발판")r.Cells[2].Value=steps;if(n=="LED 스트립"||n=="알루미늄 프로파일 / 확산커버")r.Cells[2].Value=Math.Round(length,1);}note.Text+="\r\n[실측 물량] "+steps+"단 / "+w+"×"+depth+"×"+thick+"mm / 발판 목재 약 "+volume.ToString("F3")+"m³ / LED 약 "+length.ToString("F1")+"m / 예상 부하 "+(length*J.Num(x,"watts")).ToString("F0")+"W. 참·난간·측판은 별도 산출.";UpdateSum();return true;}))f.ShowDialog(this);}
void RailingPrice(){D v=J.Row("type","미송","length",1);using(var f=new EditForm("난간 비교 · 원문 2021년 / VAT 미확인",v,new[]{new Field("type","참고 종류","select","미송,오크,기본 철재"),new Field("length","실측 연장 m","number"),new Field("cost","오름목 실제 원가 / m","number"),new Field("sale","오름목 판매 공급단가 / m","number")},null,x=>{decimal rate=J.Text(x,"type")=="미송"?170000:J.Text(x,"type")=="오크"?200000:230000;if(J.Num(x,"length")<=0||J.Num(x,"sale")<=0){MessageBox.Show("길이와 오름목 판매단가를 입력하세요.\r\n원문 참고: "+J.Money(rate)+"/m, VAT 미확인.");return false;}if(MessageBox.Show("원문 참고 합계 "+J.Money(rate*J.Num(x,"length"))+" (VAT 미확인)\r\n내 판매 공급가 "+J.Money(J.Num(x,"sale")*J.Num(x,"length"))+"\r\n원가와 판매단가를 반영할까요?","난간 가격 확인",MessageBoxButtons.YesNo)!=DialogResult.Yes)return false;items.Rows.Add("난간",J.Text(x,"type")+" 난간 (오름목 지정단가)",J.Num(x,"length"),"m",J.Num(x,"cost"),J.Num(x,"sale"));UpdateSum();return true;}))f.ShowDialog(this);}
