static class Program {static System.Threading.Mutex single;
[STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{if(args.Contains("--remote-self-test"))return RemoteValidation.Run();if(args.Contains("--self-test"))return SelfTest();bool first;single=new System.Threading.Mutex(true,"Local\\OreumMokNative"+(AppDomain.CurrentDomain.FriendlyName.IndexOf("User",StringComparison.OrdinalIgnoreCase)>=0||args.Contains("--client")?"Client":"Admin"),out first);if(!first){MessageBox.Show("오름목이 이미 실행 중입니다. 기존 창을 확인하세요.");return 0;}using(var bridge=new Bridge(AppDomain.CurrentDomain.FriendlyName.IndexOf("User",StringComparison.OrdinalIgnoreCase)>=0||args.Contains("--client"))){D user;if(bridge.IsRemote){using(var login=new RemoteLogin(bridge)){if(login.ShowDialog()!=DialogResult.OK)return 0;user=login.User;}}else{using(var login=new Login(bridge)){if(login.ShowDialog()!=DialogResult.OK)return 0;user=login.User;}}Application.Run(new MainForm(bridge,user));}return 0;}catch(Exception e){if(args.Contains("--self-test")){File.WriteAllText(Path.Combine(Environment.GetEnvironmentVariable("OREUMMOK_DATA_DIR"),"self-test-error.txt"),e.ToString());return 1;}MessageBox.Show(e.Message,"오름목 실행 오류");return 1;}}
static int SelfTest(){string dir=Environment.GetEnvironmentVariable("OREUMMOK_DATA_DIR");if(String.IsNullOrEmpty(dir)||!dir.Contains("qa-native"))throw new Exception("Self-test requires a dedicated qa-native data directory.");using(var bridge=new Bridge()){D status=bridge.Call("status");if(!J.Bool(status,"initialized")){using(var firstRun=new Login(bridge)){firstRun.Show();Application.DoEvents();using(var image=new Bitmap(firstRun.Width,firstRun.Height)){firstRun.DrawToBitmap(image,new Rectangle(0,0,firstRun.Width,firstRun.Height));image.Save(Path.Combine(dir,"native-first-run.png"));}firstRun.Close();}bridge.Call("setup",J.Row("username","qa-native","password","QA-Only-Password-157","name","검증용 계정"));}D user=J.Obj(bridge.Call("login",J.Row("username","qa-native","password","QA-Only-Password-157"))["user"]);D load=bridge.Call("load");D state=J.Obj(load["state"]);if(J.Rows(state,"projects").Count==0){state["projects"]=new[]{J.Row("id",Guid.NewGuid().ToString(),"name","QA · 데이터 검증 현장","status","실측","contract",3000000,"paid",1000000,"actualCost",700000)};bridge.Call("save",J.Row("state",state,"version",load["version"]));}D reloaded=bridge.Call("load");string roundtrip=J.Text(J.Rows(J.Obj(reloaded["state"]),"projects")[0],"name");if(roundtrip!="QA · 데이터 검증 현장")throw new Exception("UTF-8 round trip failed: "+roundtrip);D result=bridge.Call("totals",J.Row("items",new[]{J.Row("qty",2,"cost",350000)},"margin",30,"vat",true));if(J.Num(result,"total")!=1100000)throw new Exception("Native bridge calculation failed.");using(var login=new Login(bridge)){login.Show();Application.DoEvents();using(var image=new Bitmap(login.Width,login.Height)){login.DrawToBitmap(image,new Rectangle(0,0,login.Width,login.Height));image.Save(Path.Combine(dir,"native-login.png"));}login.Close();}using(var f=new MainForm(bridge,user)){f.Show();Application.DoEvents();using(var bmp=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bmp,new Rectangle(0,0,f.Width,f.Height));bmp.Save(Path.Combine(dir,"native-dashboard.png"));}f.ShowPage("projects");Application.DoEvents();using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(0,0,f.Width,f.Height));image.Save(Path.Combine(dir,"native-projects.png"));}using(var quote=new QuoteForm(bridge,state,null,row=>false)){quote.Show();Application.DoEvents();using(var image=new Bitmap(quote.Width,quote.Height)){quote.DrawToBitmap(image,new Rectangle(0,0,quote.Width,quote.Height));image.Save(Path.Combine(dir,"native-quote.png"));}quote.Close();}foreach(string kind in new[]{"straight","L","U"}){D settings=J.Row("shape",kind,"height",2800,"risers",16,"split",8,"going",260,"width",900,"thickness",30,"nosing",30,"landing",1000,"gap",100,"spaceX",5000,"spaceY",3000);D model=bridge.Call("stairs",settings);if(J.Num(model,"rise")!=175||J.Num(model,"treadCount")!=(kind=="straight"?15:14)||J.Bool(model,"safetyApproved"))throw new Exception("Geometry test failed");string obj=StairDesignForm.ToObj(model);if(obj.Split('\n').Count(line=>line.StartsWith("v "))!=J.Rows(model,"boxes").Count*8)throw new Exception("OBJ export mismatch");File.WriteAllText(Path.Combine(dir,"stairs-"+kind+".obj"),obj,Encoding.UTF8);using(var designer=new StairDesignForm(bridge,state,J.Row("id",Guid.NewGuid().ToString(),"name","QA 3D "+kind,"inputs",settings),row=>false)){designer.Show();Application.DoEvents();using(var image=new Bitmap(designer.Width,designer.Height)){designer.DrawToBitmap(image,new Rectangle(0,0,designer.Width,designer.Height));image.Save(Path.Combine(dir,"native-3d-"+kind+".png"));}designer.Close();}}ExtraValidation.Run(f,bridge,user,state,dir);BusinessValidation.Run(f,bridge,dir);f.ValidateWorkspaces(dir);RememberValidation.Run(bridge,dir);f.Close();}File.WriteAllText(Path.Combine(dir,"self-test.json"),"{\"nativeWindow\":true,\"login\":true,\"save\":true,\"calculation\":true,\"browserUsed\":false}",Encoding.UTF8);}return 0;}
